  "inlineSchema": "// The Sport Notebook Planner - Prisma Schema\n// Run `pnpm --filter @athlete-planner/database prisma generate` to generate the client.\n// Run `pnpm --filter @athlete-planner/database prisma migrate dev` to create/apply migrations.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── User & Auth ─────────────────────────────────────────────────────────────\n\nenum UserTier {\n  FREE\n  PRO\n}\n\nenum UserRole {\n  user\n  admin\n  root\n}\n\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  name      String?\n  googleId  String?  @unique\n  avatarUrl String?\n  tier      UserTier @default(FREE)\n  role      UserRole @default(user)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  privateExercises PrivateExercise[]\n  dailySchedules   DailySchedule[]\n\n  @@map(\"users\")\n}\n\n// ─── Exercise Library (Admin-managed) ────────────────────────────────────────\n\nenum MuscleGroup {\n  Chest\n  Back\n  Shoulders\n  Arms\n  Legs\n  Abs\n}\n\nenum RunningType {\n  Interval\n  Easy\n  Tempo\n  Long_Run\n}\n\nmodel GymExerciseMaster {\n  id                    String      @id @default(uuid())\n  isActive              Boolean     @default(true)\n  name                  String\n  vietnameseName        String\n  targetMuscleGroup     MuscleGroup\n  secondaryMuscleGroups String[]\n  youtubeEmbedUrl       String?\n  gifUrl                String?\n  garminExerciseEnum    String?\n  instructions          Json // Array of { level, steps, form_cues }\n  createdAt             DateTime    @default(now())\n  updatedAt             DateTime    @updatedAt\n\n  scheduleItems ScheduleItem[]\n\n  @@map(\"gym_exercise_masters\")\n}\n\nmodel RunningExerciseMaster {\n  id               String      @id @default(uuid())\n  isActive         Boolean     @default(true)\n  name             String\n  vietnameseName   String\n  runningType      RunningType\n  youtubeEmbedUrl  String?\n  gifUrl           String?\n  instructions     Json // LocalizedStringArray { vi: string[], en: string[] }\n  workoutStructure Json // Array of { phase, duration_minutes?, distance_meters? }\n  createdAt        DateTime    @default(now())\n  updatedAt        DateTime    @updatedAt\n\n  scheduleItems ScheduleItem[]\n\n  @@map(\"running_exercise_masters\")\n}\n\n// ─── Private Exercises (User-owned) ──────────────────────────────────────────\n\nmodel PrivateExercise {\n  id                String       @id @default(uuid())\n  userId            String\n  user              User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  isActive          Boolean      @default(true)\n  sportType         String // GYM | RUNNING\n  name              String\n  targetMuscleGroup MuscleGroup?\n  runningType       RunningType?\n  customNotes       String?\n  gifUrl            String?\n  createdAt         DateTime     @default(now())\n  updatedAt         DateTime     @updatedAt\n\n  scheduleItems ScheduleItem[]\n\n  @@map(\"private_exercises\")\n}\n\n// ─── Schedule System ─────────────────────────────────────────────────────────\n\nenum DayStatus {\n  PENDING\n  COMPLETED\n  SKIPPED\n  REST\n}\n\nmodel DailySchedule {\n  id         String    @id @default(uuid())\n  userId     String\n  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  dateString String // YYYY-MM-DD format\n  weekNumber Int // ISO 8601 week number\n  year       Int // ISO 8601 week year\n  dayStatus  DayStatus @default(PENDING)\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  items ScheduleItem[]\n\n  @@unique([userId, dateString])\n  @@index([userId, year, weekNumber])\n  @@map(\"daily_schedules\")\n}\n\nmodel ScheduleItem {\n  id                String        @id @default(uuid())\n  scheduleId        String\n  schedule          DailySchedule @relation(fields: [scheduleId], references: [id], onDelete: Cascade)\n  sequenceOrder     Int\n  sportType         String // GYM | RUNNING\n  isPrivateExercise Boolean       @default(false)\n\n  // Polymorphic FK: only ONE should be set\n  gymMasterId       String?\n  gymMaster         GymExerciseMaster?     @relation(fields: [gymMasterId], references: [id], onDelete: SetNull)\n  runningMasterId   String?\n  runningMaster     RunningExerciseMaster? @relation(fields: [runningMasterId], references: [id], onDelete: SetNull)\n  privateExerciseId String?\n  privateExercise   PrivateExercise?       @relation(fields: [privateExerciseId], references: [id], onDelete: SetNull)\n\n  // Payloads (nullable for FREE tier rolling cleanup)\n  gymPayload     Json? // { rest_time_seconds, sets: [{ set_number, weight_kg, reps, rpe, is_completed }] }\n  runningPayload Json? // { target_distance_km?, duration_minutes?, intensity_type, pace_target_range?, hr_target_range? }\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([scheduleId, sequenceOrder])\n  @@map(\"schedule_items\")\n}\n\n// ─── Blog / CMS ───────────────────────────────────────────────────────────────\n\nmodel BlogPost {\n  id          String    @id @default(uuid())\n  title       String\n  slug        String    @unique\n  excerpt     String    @default(\"\")\n  content     String    @default(\"\")\n  coverImage  String?\n  tags        String[]\n  categoryKey String?\n  status      String    @default(\"draft\") // draft | published | archived\n  readingTime Int       @default(5)\n  publishedAt DateTime?\n  authorId    String?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  category BlogCategory? @relation(fields: [categoryKey], references: [key])\n\n  @@map(\"blog_posts\")\n}\n\nmodel BlogCategory {\n  id          String   @id @default(uuid())\n  key         String   @unique\n  label       String\n  description String?\n  imageUrl    String?\n  isActive    Boolean  @default(true)\n  order       Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  posts BlogPost[]\n\n  @@map(\"blog_categories\")\n}\n\n// ─── Storage / Assets ─────────────────────────────────────────────────────────\n\nmodel Asset {\n  id              String   @id @default(uuid())\n  fileName        String\n  url             String\n  key             String?\n  storageProvider String   @default(\"r2\") // r2 | cloudinary\n  mimeType        String?\n  size            Int?\n  category        String?\n  uploadedBy      String?\n  createdAt       DateTime @default(now())\n\n  @@map(\"assets\")\n}\n\n// ─── App Config ───────────────────────────────────────────────────────────────\n\nmodel AppConfig {\n  id        Int      @id @default(autoincrement())\n  key       String   @unique\n  value     Json\n  label     String?\n  updatedAt DateTime @updatedAt\n\n  @@map(\"app_configs\")\n}\n",
